<?php namespace App\Filament\Resources\StudentSocialPassportResource\RelationManagers;use Filament\Forms;use Filament\Resources\Form;use Filament\Resources\RelationManagers\RelationManager;use Filament\Resources\Table;use Filament\Tables;class FollowupsRelationManager extends RelationManager{protected static string $relationship='followups';protected static ?string $title='Социальное сопровождение';public static function form(Form $f):Form{return $f->schema([Forms\Components\DatePicker::make('started_on')->label('Начало')->required(),Forms\Components\Textarea::make('reason')->label('Основание')->required(),Forms\Components\TextInput::make('responsible')->label('Ответственный'),Forms\Components\Textarea::make('actions')->label('Мероприятия'),Forms\Components\DatePicker::make('ended_on')->label('Окончание'),Forms\Components\Textarea::make('result')->label('Результат')]);}public static function table(Table $t):Table{return $t->columns([Tables\Columns\TextColumn::make('started_on')->label('Начало')->date('d.m.Y'),Tables\Columns\TextColumn::make('reason')->label('Основание')->limit(70),Tables\Columns\TextColumn::make('responsible')->label('Ответственный'),Tables\Columns\BadgeColumn::make('status')->label('Статус')])->headerActions([Tables\Actions\CreateAction::make()->label('Открыть сопровождение')->mutateFormDataUsing(fn($d)=>$d+['status'=>'active','created_by'=>auth()->id()])])->actions([Tables\Actions\EditAction::make(),Tables\Actions\Action::make('close')->label('Закрыть')->visible(fn($x)=>$x->status==='active')->action(fn($x)=>$x->update(['status'=>'closed','ended_on'=>$x->ended_on?:today()]))]);}}